<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {command,message,desktop} from '../api'
import {useDatabase} from '../stores/database'
import {useAuth} from '../stores/auth'
import TemplateTreeManager from './TemplateTreeManager.vue'
import CatalogSettings from './CatalogSettings.vue'
const settingsOpen=ref(false)
import {templatePath,sectionItems,visibleTemplate,templatePhraseParts,composeTemplate,type UserTemplate} from '../userTemplates'
const props=defineProps<{templateId?:number;pick?:boolean;referenceKey?:string}>()
const referenceSections=computed(()=>props.referenceKey?entries.value.filter(e=>e.folder&&e.key.toLowerCase().endsWith('.'+props.referenceKey!.toLowerCase())&&(!e.templateId||e.templateId===props.templateId)):[])
const emit=defineEmits<{select:[entry:UserTemplate,text?:string]}>()
const phraseEntry=ref<UserTemplate>(),phraseSelected=ref<number[]>([])
const phraseParts=computed(()=>phraseEntry.value?templatePhraseParts(phraseEntry.value,entries.value):[])
const phraseText=computed(()=>composeTemplate(phraseParts.value,phraseSelected.value))
function assemble(entry:UserTemplate){phraseEntry.value=entry;phraseSelected.value=templatePhraseParts(entry,entries.value).map(part=>part.id)}
function selectPhrasePart(id:number,checked:boolean){phraseSelected.value=checked?[...phraseSelected.value,id]:phraseSelected.value.filter(value=>value!==id)}
function insertPhrase(){if(!phraseEntry.value||!phraseText.value)return;const entry=phraseEntry.value,text=phraseText.value;phraseEntry.value=undefined;emit('select',entry,text)}
const treeOpen=ref(false),treeEntry=ref<UserTemplate>(),treeAction=ref('browse'),selectedSection=ref(0)
function openTree(action='browse',entry?:UserTemplate){treeAction.value=action;treeEntry.value=entry;treeOpen.value=true}
function entryActions(entry:UserTemplate){return [{label:'Копировать',icon:'i-lucide-copy',onSelect:()=>openTree('copy',entry)},{label:'Переместить',icon:'i-lucide-folder-input',onSelect:()=>openTree('move',entry)},{label:'Создать подраздел',icon:'i-lucide-folder-plus',onSelect:()=>openTree('create',entry)},{label:'Выше в разделе',icon:'i-lucide-arrow-up',onSelect:()=>order(entry,'up')},{label:'Ниже в разделе',icon:'i-lucide-arrow-down',onSelect:()=>order(entry,'down')}]}
async function restoreEntry(entry:UserTemplate){saving.value=true;error.value='';try{const result=await command<{entries:UserTemplate[]}>('mutate_template_tree',{input:{action:'restore',id:entry.id,revision:entry.revision||0}});entries.value=result.entries;success.value='Заготовка восстановлена.'}catch(e){error.value=message(e)}finally{saving.value=false}}
async function order(entry:UserTemplate,direction:string){saving.value=true;error.value='';try{const result=await command<{entries:UserTemplate[]}>('mutate_template_tree',{input:{action:'order',id:entry.id,revision:entry.revision||0,direction}});entries.value=result.entries;success.value='Порядок изменён.'}catch(e){error.value=message(e)}finally{saving.value=false}}
const sections=computed(()=>[{label:'Все разделы',value:0},...sectionItems(entries.value,selectedType.value,showHidden.value,showDeleted.value&&!props.pick)])
const createOpen=ref(false),createType=ref<number>(),createParent=ref<number>(),createText=ref('')
const auth=useAuth(),editing=ref<UserTemplate>(),deleting=ref<UserTemplate>(),editText=ref(''),saving=ref(false),dialogError=ref(''),success=ref(''),showDeleted=ref(false)
const db=useDatabase(),entries=ref<UserTemplate[]>([]),query=ref(''),selectedType=ref<number>(props.templateId||0),showHidden=ref(false),error=ref(''),loading=ref(true)
watch(selectedType,()=>selectedSection.value=0)
async function load(){loading.value=true;error.value='';try{if(!db.info)await db.load();entries.value=await command<UserTemplate[]>('user_templates')}catch(e){error.value=message(e)}finally{loading.value=false}}
onMounted(load)
function edit(entry:UserTemplate){editing.value=entry;editText.value=entry.value||entry.name;dialogError.value=''}
function requestDelete(entry:UserTemplate){deleting.value=entry;dialogError.value=''}
async function save(entry:UserTemplate,text:string,deleted:boolean){
 saving.value=true;dialogError.value='';error.value='';success.value=''
 try{const result=await command<{text:string;deleted:boolean;revision:number}>('save_user_template',{id:entry.id,revision:entry.revision||0,text,deleted});Object.assign(entry,{value:result.text,deleted:result.deleted,revision:result.revision});editing.value=undefined;deleting.value=undefined;success.value=deleted?'Заготовка удалена. Её можно восстановить через «Показать удалённые».':'Заготовка сохранена.'}catch(e){if(editing.value||deleting.value)dialogError.value=message(e);else error.value=message(e)}finally{saving.value=false}
}

const items=computed(()=>[{label:'Все виды исследований',value:0},...(db.info?.templates||[]).map(t=>({label:t.name,value:t.id}))])
const createTypes=computed(()=>(db.info?.templates||[]).filter(t=>!t.hidden).map(t=>({label:t.name,value:t.id})))
const createSections=computed(()=>!createType.value?[]:entries.value.filter(e=>e.folder&&[...templatePath(e,entries.value),e].every(p=>!p.hidden&&!p.deleted&&(!p.templateId||p.templateId===createType.value))).map(e=>({label:[...templatePath(e,entries.value),e].map(p=>p.name).join(' / '),value:e.id})))
watch(createType,()=>{createParent.value=undefined})
function beginCreate(){createType.value=selectedType.value||undefined;createParent.value=undefined;createText.value='';dialogError.value='';createOpen.value=true}
async function create(){
 if(!createType.value||!createParent.value||!createText.value.trim())return
 saving.value=true;dialogError.value='';success.value=''
 try{const entry=await command<UserTemplate>('create_user_template',{templateId:createType.value,parentId:createParent.value,text:createText.value});entries.value.unshift(entry);selectedType.value=createType.value;query.value='';createOpen.value=false;success.value='Новая заготовка добавлена.'}catch(e){dialogError.value=message(e)}finally{saving.value=false}
}
const rows=computed(()=>entries.value.filter(e=>!e.folder).map(entry=>({entry,path:templatePath(entry,entries.value)})).filter(({entry,path})=>(!props.referenceKey||path.some(p=>referenceSections.value.some(s=>s.id===p.id)))&&visibleTemplate(entry,path,showHidden.value,!props.pick&&showDeleted.value)&&(!selectedType.value||entry.templateId===selectedType.value||(!entry.templateId&&path.some(p=>p.templateId===selectedType.value)))&&(!selectedSection.value||path.some(p=>p.id===selectedSection.value))&&[...path.map(p=>p.name),entry.name,entry.value].join(' ').toLocaleLowerCase('ru').includes(query.value.trim().toLocaleLowerCase('ru'))))
</script>
<template><div><UAlert v-if="success" color="success" :description="success" class="mb-5"/><UAlert v-if="error" color="error" :description="error" class="mb-5"/><div class="grid gap-4 md:grid-cols-2 mb-5"><UFormField label="Поиск по тексту и разделу"><UInput v-model="query" icon="i-lucide-search" placeholder="Найти заготовку…" class="w-full"/></UFormField><UFormField v-if="!referenceKey" label="Вид исследования"><USelect v-model="selectedType" :items="items" class="w-full"/></UFormField></div><UFormField v-if="!referenceKey" label="Раздел" class="mb-5"><USelect v-model="selectedSection" :items="sections" class="w-full"/></UFormField><div class="flex flex-wrap items-center gap-5 mb-5"><UCheckbox :ui="{root:'items-center',container:'h-auto',label:'block'}" v-model="showHidden" label="Показать скрытые в старой программе"/><UCheckbox :ui="{root:'items-center',container:'h-auto',label:'block'}" v-if="!pick&&auth.canWrite" v-model="showDeleted" label="Показать удалённые"/><UButton v-if="!pick" variant="ghost" color="neutral" icon="i-lucide-refresh-cw" :disabled="loading||saving" @click="load">Обновить</UButton><UButton v-if="!pick&&auth.canWrite" icon="i-lucide-folder-tree" variant="outline" :disabled="!desktop||loading||saving" @click="openTree()">Разделы</UButton><UButton v-if="!pick&&auth.admin" icon="i-lucide-settings-2" variant="ghost" color="neutral" :disabled="!desktop||loading||saving" @click="settingsOpen=true">Настройки видов</UButton><UButton v-if="!pick&&auth.canWrite" icon="i-lucide-plus" class="ms-auto" :disabled="!desktop||loading||saving" @click="beginCreate">Новая заготовка</UButton></div><p v-if="loading" role="status">Загружаем справочник…</p><template v-else><p class="mb-4 text-slate-600" role="status">Найдено заготовок: {{rows.length}}</p><p v-if="referenceKey&&!referenceSections.length">В базе нет раздела справочника для этого поля. Создайте его через «Справочник шаблонов» → «Настройки видов» → «Синхронизировать разделы», затем добавьте заготовки.</p><p v-else-if="!rows.length">Заготовок не найдено. Измените поиск или добавьте заготовку в справочник.</p><ul class="template-card-list">
  <li v-for="{entry,path} in rows" :key="entry.id" class="template-card">
    <p class="template-card-path">{{path.map(p=>p.name).join(' / ')}}<span v-if="entry.deleted"> · Удалена</span><span v-else-if="path.some(p=>p.deleted)"> · Раздел удалён</span><span v-if="entry.hidden"> · Скрытая запись</span></p>
    <p class="template-card-text preserve-lines">{{entry.value||entry.name}}</p>
    <div v-if="pick&&!entry.deleted||!pick&&auth.canWrite" class="template-card-actions">
      <template v-if="pick&&!entry.deleted"><UButton variant="ghost" icon="i-lucide-plus" aria-label="Вставить" title="Вставить заготовку" @click="emit('select',entry)"/><UButton variant="ghost" color="neutral" icon="i-lucide-list-tree" aria-label="Собрать фразу из ветви" title="Собрать фразу из ветви" @click="assemble(entry)"/></template>
      <template v-else-if="!entry.deleted&&!entry.hidden">
        <UButton variant="ghost" color="neutral" icon="i-lucide-pencil" aria-label="Изменить" title="Изменить заготовку" :disabled="!desktop||saving" @click="edit(entry)"/>
        <UButton variant="ghost" color="error" icon="i-lucide-trash-2" aria-label="Удалить" title="Удалить заготовку" :disabled="!desktop||saving" @click="requestDelete(entry)"/>
      <UDropdownMenu :items="entryActions(entry)"><UButton icon="i-lucide-ellipsis" variant="ghost" color="neutral" aria-label="Действия с заготовкой" title="Действия с заготовкой" :disabled="!desktop||saving"/></UDropdownMenu></template>
      <UButton v-else variant="ghost" icon="i-lucide-undo-2" aria-label="Восстановить" title="Восстановить заготовку" :disabled="!desktop||saving" @click="restoreEntry(entry)"/>
    </div>
  </li>
</ul></template>
<UModal :open="Boolean(phraseEntry)" @update:open="(value:boolean)=>{if(!value)phraseEntry=undefined}" title="Составная фраза" description="Выберите части текста в порядке ветви. Служебные названия разделов в текст не входят."><template #body><div class="grid gap-4 mb-5"><UCheckbox v-for="part in phraseParts" :key="part.id" :model-value="phraseSelected.includes(part.id)" @update:model-value="selectPhrasePart(part.id,Boolean($event))" :label="part.text" :ui="{root:'items-center',container:'h-auto',label:'block'}"/></div><p class="text-slate-600 mb-2">Будет добавлено</p><p class="preserve-lines phrase-preview">{{phraseText||'Выберите хотя бы одну часть'}}</p></template><template #footer><UButton color="neutral" variant="outline" @click="phraseEntry=undefined">Отмена</UButton><UButton :disabled="!phraseText" @click="insertPhrase">Вставить фразу</UButton></template></UModal>
<CatalogSettings v-if="settingsOpen" v-model:open="settingsOpen" @changed="load"/>
<TemplateTreeManager v-if="treeOpen" v-model:open="treeOpen" :entries="entries" :initial-entry="treeEntry" :initial-action="treeAction" @changed="entries=$event"/>
<UModal :open="createOpen" @update:open="(value:boolean)=>{if(!saving)createOpen=value}" :dismissible="!saving" title="Новая заготовка" description="Выберите вид исследования и раздел, в котором будет храниться текст."><template #body><UAlert v-if="dialogError" color="error" :description="dialogError" class="mb-4"/><div class="grid gap-5"><UFormField label="Вид исследования" required><USelect v-model="createType" :items="createTypes" placeholder="Выберите исследование" class="w-full" :disabled="saving"/></UFormField><UFormField label="Раздел справочника" required><USelect v-model="createParent" :items="createSections" :disabled="saving||!createType" placeholder="Выберите раздел" class="w-full"/></UFormField><UFormField label="Текст заготовки" required><UTextarea v-model="createText" :rows="6" autoresize class="w-full" :disabled="saving"/></UFormField></div></template><template #footer><UButton color="neutral" variant="outline" :disabled="saving" @click="createOpen=false">Отмена</UButton><UButton :loading="saving" :disabled="saving||!createType||!createParent||!createText.trim()" @click="create">Добавить</UButton></template></UModal>
<UModal :open="Boolean(editing)" @update:open="(value:boolean)=>{if(!value&&!saving)editing=undefined}" :dismissible="!saving" title="Изменить заготовку" description="Изменения будут использоваться при следующих вставках. Текст сохранённых исследований останется прежним."><template #body><p v-if="editing" class="text-sm text-slate-500 mb-4">{{templatePath(editing,entries).map(p=>p.name).join(' / ')}}</p><UAlert v-if="dialogError" color="error" :description="dialogError" class="mb-4"/><UFormField label="Текст заготовки" required><UTextarea v-model="editText" :rows="8" autoresize class="w-full" :disabled="saving"/></UFormField></template><template #footer><UButton color="neutral" variant="outline" :disabled="saving" @click="editing=undefined">Отмена</UButton><UButton :loading="saving" :disabled="saving||!editText.trim()" @click="editing&&save(editing,editText,false)">Сохранить</UButton></template></UModal>
<UModal :open="Boolean(deleting)" @update:open="(value:boolean)=>{if(!value&&!saving)deleting=undefined}" :dismissible="!saving" title="Удалить заготовку?" description="Она исчезнет из списка вставки. Сохранённые исследования не изменятся. Заготовку можно будет восстановить."><template #body><UAlert v-if="dialogError" color="error" :description="dialogError" class="mb-4"/><p class="preserve-lines">{{deleting?.value||deleting?.name}}</p></template><template #footer><UButton color="neutral" variant="outline" :disabled="saving" @click="deleting=undefined">Отмена</UButton><UButton color="error" :loading="saving" :disabled="saving" @click="deleting&&save(deleting,deleting.value||deleting.name,true)">Удалить заготовку</UButton></template></UModal>
</div></template>
